-- Ghana: ES/DE/FR milestone translations, from the scaffolder's
-- drafts/ stub, translated and moved into the numbered sequence.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES
 ('gh-evat-pilot', 'es', 'El piloto de E-VAT arranca con unos cincuenta grandes contribuyentes', 'La GRA comenzó a pilotar el Sistema Certificado de Facturación con unos cincuenta grandes contribuyentes. El plan publicado entonces situaba la Fase 1 hasta junio de 2023, la Fase 2 hasta diciembre de 2023 y a todos los inscritos en el IVA para diciembre de 2024. Ninguna de esas fechas se cumplió.',
  '["Lea el plan de fases de 2023 como intención, no como registro"]'),
 ('gh-evat-phase1', 'es', 'Fase 1: seiscientos contribuyentes inscritos en el IVA', 'La GRA convocó a seiscientos contribuyentes nombrados a reuniones obligatorias de incorporación en Accra. Es la fase que el plan de 2023 había fijado entre marzo y junio de 2023; ocurrió aproximadamente un año más tarde.',
  '["Sustituida por el deber general de la Ley 1151"]'),
 ('gh-evat-phase2', 'es', 'Fase 2: dos mil contribuyentes más', 'Otros dos mil contribuyentes inscritos en el IVA fueron designados para incorporarse, repartidos en siete oficinas tributarias de Accra. La GRA describió el propósito como el seguimiento en tiempo real de las operaciones de IVA. No se emitió aviso alguno de la GRA para fases posteriores.',
  '["Sustituida por el deber general de la Ley 1151"]'),
 ('gh-act1151-cis-duty', 'es', 'La Ley 1151 convierte la facturación certificada en un deber general de todo sujeto pasivo', 'La Ley del Impuesto sobre el Valor Añadido de 2025 (Ley 1151) sustituyó a la Ley 870 y, en su artículo 43(2), exige que todo sujeto pasivo emita facturas mediante un Sistema Certificado de Facturación integrado con el del Comisionado General. La obligación dejó de ser un programa por fases dirigido a contribuyentes nombrados. Esa misma fecha abolió la Tasa COVID-19 de Recuperación Sanitaria, situó el tipo global en el 20 %, elevó el umbral de registro para bienes a 750.000 GHS, eliminó por completo el umbral para servicios, suprimió el Régimen de Tipo Fijo del IVA y multiplicó por cien el techo sancionador de la facturación.',
  '["Si está inscrito en el IVA en Ghana, ya está dentro del ámbito", "Prestadores de servicios: no hay umbral alguno; regístrese en 30 días desde el inicio de la actividad", "Integre un sistema acreditado o use el software E-VAT gratuito de la GRA"]'),
 ('gh-fed-expenditure-approved', 'es', 'El Parlamento aprueba el despliegue de dispositivos fiscales electrónicos', 'El Parlamento aprobó un compromiso de gasto plurianual para la política de Dispositivos Fiscales Electrónicos de la Ley 966, con el objetivo de cuarenta mil aparatos en puntos de venta minoristas. Las informaciones situaban el fin del piloto en agosto de 2026 y el despliegue a continuación. Se trata de equipamiento de fiscalización minorista, no de un cambio en el deber de facturar, que la Ley 1151 ya generalizó.',
  '["Minoristas: prevean el despliegue de dispositivos, empezando por comercios medianos", "Los tiques fiscales de la Ley 966 ya satisfacen el deber de facturar según el art. 43(9) de la Ley 1151"]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES
 ('gh-evat-pilot', 'de', 'Der E-VAT-Pilot startet mit rund fünfzig Grosssteuerpflichtigen', 'Die GRA begann den Pilotbetrieb des zertifizierten Rechnungssystems mit etwa fünfzig Grosssteuerpflichtigen. Der damals veröffentlichte Plan sah Phase 1 bis Juni 2023, Phase 2 bis Dezember 2023 und alle MWST-Registrierten bis Dezember 2024 vor. Keiner dieser Termine wurde gehalten.',
  '["Den Phasenplan von 2023 als Absicht lesen, nicht als Nachweis"]'),
 ('gh-evat-phase1', 'de', 'Phase 1: sechshundert umsatzsteuerlich registrierte Steuerpflichtige', 'Die GRA lud sechshundert namentlich genannte Steuerpflichtige zu verbindlichen Onboarding-Treffen in Accra. Es ist die Phase, die der Plan von 2023 auf März bis Juni 2023 gelegt hatte; sie fand rund ein Jahr später statt.',
  '["Durch die allgemeine Pflicht des Gesetzes 1151 überholt"]'),
 ('gh-evat-phase2', 'de', 'Phase 2: weitere zweitausend Steuerpflichtige', 'Weitere zweitausend umsatzsteuerlich registrierte Steuerpflichtige wurden über sieben Steuerämter in Accra zum Onboarding benannt. Die GRA nannte als Zweck die Echtzeitüberwachung von MWST-Transaktionen. Für spätere Phasen erging keine Mitteilung der GRA.',
  '["Durch die allgemeine Pflicht des Gesetzes 1151 überholt"]'),
 ('gh-act1151-cis-duty', 'de', 'Gesetz 1151 macht die zertifizierte Rechnungsstellung zur allgemeinen Pflicht jedes Steuerpflichtigen', 'Das Mehrwertsteuergesetz 2025 (Gesetz 1151) ersetzte das Gesetz 870 und verlangt in Art. 43(2) von jedem Steuerpflichtigen, Rechnungen über ein zertifiziertes Rechnungssystem auszustellen, das mit dem des Commissioner-General verbunden ist. Die Pflicht war damit kein Phasenprogramm für namentlich benannte Steuerpflichtige mehr. Zum selben Datum entfiel die COVID-19-Abgabe, sank der Gesamtsatz auf 20 %, stieg die Registrierungsschwelle für Waren auf 750.000 GHS, entfiel die Schwelle für Dienstleistungen vollständig, wurde das MWST-Pauschalsystem abgeschafft und die Sanktionsobergrenze verhundertfacht.',
  '["Wer in Ghana umsatzsteuerlich registriert ist, ist jetzt erfasst", "Dienstleister: Es gibt gar keine Schwelle -- Registrierung binnen 30 Tagen ab Aufnahme der Tätigkeit", "Ein akkreditiertes System integrieren oder die kostenlose E-VAT-Software der GRA nutzen"]'),
 ('gh-fed-expenditure-approved', 'de', 'Das Parlament bewilligt die Einführung fiskalischer elektronischer Geräte', 'Das Parlament bewilligte eine mehrjährige Ausgabenverpflichtung für die Politik der fiskalischen elektronischen Geräte nach Gesetz 966 mit dem Ziel von vierzigtausend Geräten an Einzelhandelskassen. Berichten zufolge endete der Pilot im August 2026, danach folgt die Ausbringung. Es handelt sich um Kassenfiskalisierung, nicht um eine Änderung der Rechnungspflicht, die Gesetz 1151 bereits verallgemeinert hat.',
  '["Einzelhandel: mit der Geräteausbringung rechnen, beginnend bei mittelgrossen Geschäften", "Fiskalbelege nach Gesetz 966 erfüllen die Rechnungspflicht bereits gemäss Art. 43(9) des Gesetzes 1151"]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES
 ('gh-evat-pilot', 'fr', 'Le pilote E-VAT démarre avec une cinquantaine de grands contribuables', 'La GRA a lancé le pilote du système certifié de facturation auprès d''une cinquantaine de grands contribuables. Le plan publié alors prévoyait la phase 1 jusqu''en juin 2023, la phase 2 jusqu''en décembre 2023 et l''ensemble des assujettis pour décembre 2024. Aucune de ces échéances n''a été tenue.',
  '["Lire le plan de phases de 2023 comme une intention, non comme un constat"]'),
 ('gh-evat-phase1', 'fr', 'Phase 1 : six cents assujettis à la TVA', 'La GRA a convoqué six cents contribuables nommément désignés à des réunions obligatoires d''intégration à Accra. C''est la phase que le plan de 2023 situait entre mars et juin 2023 ; elle a eu lieu environ un an plus tard.',
  '["Remplacée par l''obligation générale de la loi 1151"]'),
 ('gh-evat-phase2', 'fr', 'Phase 2 : deux mille contribuables supplémentaires', 'Deux mille assujettis supplémentaires ont été désignés pour l''intégration, répartis sur sept centres des impôts d''Accra. La GRA a présenté l''objectif comme le suivi en temps réel des opérations de TVA. Aucun avis de la GRA n''a été publié pour les phases ultérieures.',
  '["Remplacée par l''obligation générale de la loi 1151"]'),
 ('gh-act1151-cis-duty', 'fr', 'La loi 1151 fait de la facturation certifiée une obligation générale de tout assujetti', 'La loi de 2025 sur la taxe sur la valeur ajoutée (loi 1151) a remplacé la loi 870 et impose, à son article 43(2), que tout assujetti émette ses factures au moyen d''un système certifié de facturation relié à celui du Commissioner-General. L''obligation a cessé d''être un programme par phases visant des contribuables nommés. La même date a supprimé la taxe COVID-19, porté le taux global à 20 %, relevé le seuil d''assujettissement pour les biens à 750 000 GHS, supprimé tout seuil pour les services, aboli le régime de taux forfaitaire et centuplé le plafond de sanction.',
  '["Si vous êtes assujetti à la TVA au Ghana, vous êtes désormais dans le champ", "Prestataires de services : il n''existe aucun seuil -- inscrivez-vous dans les 30 jours du début d''activité", "Intégrer un système accrédité, ou utiliser le logiciel E-VAT gratuit de la GRA"]'),
 ('gh-fed-expenditure-approved', 'fr', 'Le Parlement approuve le déploiement des appareils fiscaux électroniques', 'Le Parlement a approuvé un engagement de dépense pluriannuel pour la politique des appareils fiscaux électroniques prévue par la loi 966, visant quarante mille appareils aux points de vente de détail. La presse situait la fin du pilote en août 2026, le déploiement suivant. Il s''agit de matériel de fiscalisation du commerce de détail, non d''une modification de l''obligation de facturer, que la loi 1151 a déjà généralisée.',
  '["Détaillants : anticiper le déploiement des appareils, à commencer par les commerces moyens", "Les tickets fiscaux de la loi 966 satisfont déjà l''obligation de facturer selon l''art. 43(9) de la loi 1151"]');

